CREATE OR REPLACE FUNCTION public.create_guild_v2(p_user_id uuid, p_guild_name text, p_creation_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user public.users%rowtype; v_name text:=trim(coalesce(p_guild_name,'')); v_guild uuid;
begin
 if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only the current user can create a guild' using errcode='42501'; end if;
 if char_length(v_name) not between 1 and 12 or p_creation_cost<>500 then raise exception 'Invalid guild creation request' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':guild-create',0));
 select * into v_user from public.users where id=auth.uid() for update;
 if not found or v_user.level<5 or v_user.cash<500 then raise exception 'Guild creation requirements are not met' using errcode='P0001'; end if;
 if v_user.guild_id is not null or exists(select 1 from public.guild_members where user_id=auth.uid()) then raise exception 'Leave the current guild before creating another guild' using errcode='23505'; end if;
 perform 1 from public.guilds where lower(trim(name))=lower(v_name) and not is_disbanded for update;
 if found then raise exception 'Guild name is already in use' using errcode='23505'; end if;
 update public.guild_join_requests set status='CANCELLED',reviewed_at=now(),reviewed_by=auth.uid() where user_id=auth.uid() and status='PENDING';
 insert into public.guilds(name,leader_id,level,xp,funds,recruitment_mode,approval_required) values(v_name,auth.uid(),1,0,0,'OPEN_JOIN',false) returning id into v_guild;
 insert into public.guild_members(guild_id,user_id,role,weekly_contribution,total_contribution) values(v_guild,auth.uid(),'MASTER',0,0);
 update public.users set cash=cash-500,guild_id=v_guild where id=auth.uid();
 perform public.evaluate_mission_progress(auth.uid(),'GUILD_JOIN',1);
 return jsonb_build_object('status','success','guild_id',v_guild,'cash_spent',500);
end $function$

CREATE OR REPLACE FUNCTION public.initialize_current_player(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_username text:=btrim(p_username);
  v_is_anonymous boolean:=coalesce((auth.jwt()->>'is_anonymous')::boolean,false);
begin
  if v_user_id is null then raise exception 'Authentication is required'; end if;
  if not v_is_anonymous then raise exception 'Anonymous onboarding session is required'; end if;
  if v_username is null or char_length(v_username) not between 1 and 8 then
    raise exception 'Username must contain 1 to 8 characters';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_user_id::text,0));
  if exists(select 1 from public.users where id=v_user_id) then
    insert into public.tutorial_progress(user_id,step_id) values(v_user_id,'WORLD_INTRO') on conflict(user_id) do nothing;
    return jsonb_build_object('status','already_initialized','tutorial_step',(select step_id from public.tutorial_progress where user_id=v_user_id));
  end if;
  if exists(select 1 from public.users where lower(btrim(username))=lower(v_username)) then
    raise exception 'Username is already in use' using errcode='23505';
  end if;
  insert into public.users(id,username,current_base_id,favorite_character_id)
  values(v_user_id,v_username,'shinjuku',null);
  insert into public.tutorial_progress(user_id,step_id) values(v_user_id,'WORLD_INTRO') on conflict(user_id) do nothing;
  return jsonb_build_object('status','success','tutorial_step','WORLD_INTRO');
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_current_player(p_username text, p_invite_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb; v_invitation jsonb;
begin
 v_result:=public.initialize_current_player(p_username);
 if v_result->>'status'='success' and nullif(btrim(coalesce(p_invite_code,'')),'') is not null then
  v_invitation:=public.apply_current_player_invitation(p_invite_code);
  v_result:=v_result||jsonb_build_object('invitation',v_invitation);
 end if;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.join_guild(p_guild_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mode text;
  v_cap integer;
  v_count integer;
  v_user public.users%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication is required'; end if;
  select * into v_user from public.users where id = auth.uid() for update;
  if not found then raise exception 'Guild joining requirements are not met'; end if;
  if v_user.last_guild_left_at is not null and v_user.last_guild_left_at > now() - interval '24 hours' then
    raise exception 'Guild rejoin cooldown is active'
      using errcode = 'P0001', detail = 'GUILD_JOIN_COOLDOWN_ACTIVE';
  end if;
  if exists(select 1 from public.guild_members where user_id = auth.uid()) then raise exception 'Already in a guild'; end if;
  select recruitment_mode, public.canonical_guild_member_cap(id)
    into v_mode, v_cap
  from public.guilds
  where id = p_guild_id and not is_disbanded
  for update;
  if not found then raise exception 'Guild not found'; end if;
  if v_mode <> 'OPEN_JOIN' then raise exception 'Guild does not accept direct joins'; end if;
  select count(*) into v_count from public.guild_members where guild_id = p_guild_id;
  if v_count >= v_cap then raise exception 'Guild member cap reached'; end if;
  insert into public.guild_members(guild_id, user_id, role, weekly_contribution, total_contribution)
  values(p_guild_id, auth.uid(), 'MEMBER', 0, 0);
  update public.guild_join_requests
  set status = 'CANCELLED', reviewed_at = now(), reviewed_by = auth.uid()
  where user_id = auth.uid() and status = 'PENDING';
  perform public.evaluate_mission_progress(auth.uid(), 'GUILD_JOIN', 1);
  return jsonb_build_object('status', 'success');
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_ensure_subject(p_user_id uuid, p_registered_at timestamp with time zone DEFAULT now(), p_registration_type text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_subject_id uuid;
  v_registration_type text := p_registration_type;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required' using errcode = '22004';
  end if;

  select subject_id into v_subject_id
  from public.kpi_subjects
  where source_user_id = p_user_id;
  if v_subject_id is not null then
    return v_subject_id;
  end if;

  if v_registration_type is null then
    select case when au.is_anonymous then 'anonymous' else 'authenticated' end
    into v_registration_type
    from auth.users au
    where au.id = p_user_id;
  end if;
  v_registration_type := coalesce(v_registration_type, 'unknown');

  begin
    insert into public.kpi_subjects(source_user_id, registered_at, registration_type)
    values(p_user_id, coalesce(p_registered_at, now()), v_registration_type)
    returning subject_id into v_subject_id;
  exception when unique_violation then
    select subject_id into v_subject_id
    from public.kpi_subjects
    where source_user_id = p_user_id;
  end;

  return v_subject_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.leave_guild(p_user_id uuid, p_guild_id uuid, p_is_master boolean, p_has_others boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;v_other integer;
begin if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only current user can leave Guild'; end if;
 perform 1 from public.guilds where id=p_guild_id for update; select role into v_role from public.guild_members where guild_id=p_guild_id and user_id=auth.uid() for update;
 if v_role is null then raise exception 'Guild membership required'; end if; select count(*) into v_other from public.guild_members where guild_id=p_guild_id and user_id<>auth.uid();
 if v_role='MASTER' and v_other>0 then raise exception 'Transfer MASTER before leaving Guild'; end if;
 delete from public.guild_members where guild_id=p_guild_id and user_id=auth.uid(); update public.users set last_guild_left_at=now() where id=auth.uid();
 if v_role='MASTER' then update public.guilds set is_disbanded=true,disbanded_at=now(),recruitment_mode='CLOSED',approval_required=false where id=p_guild_id; end if;
 return jsonb_build_object('status','success','disbanded',v_role='MASTER'); end $function$
